from dataclasses import dataclass


@dataclass
class FixedWindow:
    limit: int
    seconds: float
    start: float = 0.0
    count: int = 0

    def allow(self, now: float) -> bool:
        if now - self.start > self.seconds:
            self.start, self.count = now, 0
        if self.count >= self.limit:
            return False
        self.count += 1
        return True
